import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

// roundCents tests
test('roundCents rounds 124.5 to 124 (even)', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents rounds 125.5 to 126 (even)', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds 2.4 down to 2', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents rounds -0.5 to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents returns exact integer unchanged', () => {
  assert.equal(roundCents(100), 100);
});

test('roundCents handles negative numbers', () => {
  assert.equal(roundCents(-123.5), -124);
});

// formatEuros tests
test('formatEuros formats 123456 as €1,234.56', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros formats -5 as -€0.05', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('formatEuros formats 0 as €0.00', () => {
  assert.equal(formatEuros(0), '€0.00');
});

test('formatEuros includes thousands separator', () => {
  assert.equal(formatEuros(1000000), '€10,000.00');
});

// parseEuros tests
test('parseEuros parses "12" as 1200 cents', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros parses "12.5" as 1250 cents', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros parses "1,234.56" as 123456 cents', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros rejects invalid input', () => {
  const result = parseEuros('invalid');
  assert.equal(result.ok, false);
});

// RATES tests
test('RATES contains EUR, USD, GBP', () => {
  assert(RATES.hasOwnProperty('EUR'));
  assert(RATES.hasOwnProperty('USD'));
  assert(RATES.hasOwnProperty('GBP'));
});

test('EUR rate is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('USD rate is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('GBP rate is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

// convert tests
test('convert EUR to USD', () => {
  // 100 EUR cents = 1 EUR = 1.085 USD ≈ 108.5 USD cents → 108 or 109 after rounding
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  // 100 EUR cents = 1 EUR = 0.8425 GBP = 84.25 GBP cents → 84 after rounding
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(12345, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert handles zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert large amounts correctly', () => {
  const result = convert(123456789, 'USD');
  assert.equal(result.ok, true);
  assert(result.value > 0);
});

test('convert rounds to whole cents', () => {
  // 123 EUR cents * 1.085 = 133.455 USD cents → 133 (banker's rounding)
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

// formatMoney tests
test('formatMoney formats EUR correctly', () => {
  const result = formatMoney(123456, 'EUR');
